/**
 * Returns a deterministic avatar from the student anonId.
 */
export function defaultAvatarFor(anonId: string): AvatarId {
  if (!anonId) return "f01";
  let hash = 0;
  for (let i = 0; i < anonId.length; i++) {
    hash = (hash * 31 + anonId.charCodeAt(i)) & 0xffffffff;
  }
  const index = Math.abs(hash) % ALL_AVATARS.length;
  return ALL_AVATARS[index].id;
}

/**
 * Renders avatar SVG XML colored with theme ink and paper.
 */
export function getAvatarXml(id: AvatarId, ink: string, paper: string): string {
  const raw = AVATAR_SVGS[id] || AVATAR_SVGS["f01"];
  // SVG masks determine alpha from luminance; in dark mode a dark mask fill makes the avatar transparent.
  // We keep mask fill white so avatar lines and shapes stay completely visible in both light & dark mode.
  const withWhiteMask = raw.replace(/<mask id="([^"]*)"><rect([^>]*)fill="__PAPER__"/g, '<mask id="$1"><rect$2fill="white"');
  return withWhiteMask.replaceAll("__INK__", ink).replaceAll("__PAPER__", paper);
}
